ALTER TABLE public.company_settings ADD COLUMN claim_incentive_staff_visible boolean NOT NULL DEFAULT true;
COMMENT ON COLUMN public.company_settings.claim_incentive_staff_visible IS 'Controls staff incentive displays and own-ledger reads; does not stop accrual or office review.';
CREATE OR REPLACE FUNCTION public.staff_incentives_visible() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.member_is_active(auth.uid()) AND coalesce((SELECT claim_incentive_staff_visible FROM public.company_settings WHERE company_id=public.current_company_id()),false); $$;
REVOKE ALL ON FUNCTION public.staff_incentives_visible() FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.staff_incentives_visible() TO authenticated;
ALTER POLICY incentive_read ON public.job_claim_incentives USING(company_id=public.current_company_id() AND public.member_is_active(auth.uid()) AND ((user_id=auth.uid() AND public.staff_incentives_visible()) OR public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'superuser')));
CREATE OR REPLACE FUNCTION public.open_job_incentives() RETURNS TABLE(job_id uuid,amount_cents integer) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT j.id,j.claim_incentive_cents FROM public.jobs j JOIN public.open_jobs_for_me() o ON o.id=j.id WHERE j.company_id=public.current_company_id() AND (public.staff_incentives_visible() OR public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'superuser')); $$;
CREATE FUNCTION public.guard_staff_incentive_visibility() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF (TG_OP='UPDATE' AND NEW.claim_incentive_staff_visible IS DISTINCT FROM OLD.claim_incentive_staff_visible) OR (TG_OP='INSERT' AND NOT NEW.claim_incentive_staff_visible) THEN IF NOT (public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'superuser')) THEN RAISE EXCEPTION 'Office access required for staff incentive visibility'; END IF; END IF; RETURN NEW; END $$;
CREATE TRIGGER staff_incentive_visibility_guard BEFORE INSERT OR UPDATE ON public.company_settings FOR EACH ROW EXECUTE FUNCTION public.guard_staff_incentive_visibility();